CREATE TABLE service_application (id UUID PRIMARY KEY, tenant_id VARCHAR(100) NOT NULL, plan_code VARCHAR(100) NOT NULL, status VARCHAR(30) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT ck_application_status CHECK (status IN ('REQUESTED','ACTIVE','CANCELLED')));
CREATE TABLE service_saga (id UUID PRIMARY KEY, application_id UUID NOT NULL REFERENCES service_application(id), tenant_id VARCHAR(100) NOT NULL, status VARCHAR(30) NOT NULL, compensation_attempts INTEGER NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT ck_saga_status CHECK (status IN ('STARTED','RESOURCE_ALLOCATED','COMPLETED','COMPENSATING','COMPENSATED','MANUAL_REQUIRED')));
CREATE TABLE outbox_event (id UUID PRIMARY KEY, tenant_id VARCHAR(100) NOT NULL, event_type VARCHAR(100) NOT NULL, payload VARCHAR(2000) NOT NULL, status VARCHAR(20) NOT NULL, occurred_at TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT ck_outbox_status CHECK (status IN ('PENDING','PUBLISHED')));
CREATE TABLE processed_event (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, consumer_name VARCHAR(100) NOT NULL, event_id UUID NOT NULL, tenant_id VARCHAR(100) NOT NULL, processed_at TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT uk_consumer_event UNIQUE (consumer_name,event_id));
CREATE INDEX ix_outbox_pending ON outbox_event(tenant_id,status,occurred_at); CREATE INDEX ix_saga_tenant ON service_saga(tenant_id,id);
